export function buildLoopAutodeletedPayload(entry, pendingCount) {
    return {
        loopId: entry.id,
        prompt: entry.prompt,
        trigger: entry.trigger,
        recurring: entry.recurring,
        autoTask: entry.autoTask,
        taskBacklog: entry.taskBacklog,
        readOnly: entry.readOnly,
        maxFires: entry.maxFires,
        fireCount: entry.fireCount,
        createdAt: entry.createdAt,
        updatedAt: entry.updatedAt,
        expiresAt: entry.expiresAt,
        source: "task_backlog_runtime",
        reason: "task_backlog_empty",
        pendingCount,
    };
}
export function buildLoopExpiredPayload(entry, disposition, source, reason, expiredAt) {
    return {
        loopId: entry.id,
        prompt: entry.prompt,
        trigger: entry.trigger,
        recurring: entry.recurring,
        createdAt: entry.createdAt,
        expiresAt: entry.expiresAt,
        expiredAt,
        disposition,
        source,
        reason,
    };
}
export function buildTaskBacklogEmptyPayload(deletedLoopIds) {
    return {
        pendingCount: 0,
        deletedLoopIds,
        source: "task_backlog_runtime",
    };
}
